import{_ as a,o as i,c as t,a5 as e}from"./chunks/framework.DJo0M80U.js";const c=JSON.parse('{"title":"网站 SEO 入门：收录、排名与上线检查清单","description":"从爬虫可发现、sitemap 提交、页面 meta 到结构化数据与国内备案，梳理网站被搜索引擎收录并提升排名的实操步骤。","frontmatter":{"title":"网站 SEO 入门：收录、排名与上线检查清单","date":"2026-06-04T00:00:00.000Z","tags":["SEO","搜索引擎","站长工具","VitePress"],"categories":["平台与博客"],"description":"从爬虫可发现、sitemap 提交、页面 meta 到结构化数据与国内备案，梳理网站被搜索引擎收录并提升排名的实操步骤。"},"headers":[],"relativePath":"posts/运维/seo/网站 SEO 入门：收录、排名与上线检查清单.md","filePath":"posts/运维/seo/网站 SEO 入门：收录、排名与上线检查清单.md","lastUpdated":1790163617000}'),l={name:"posts/运维/seo/网站 SEO 入门：收录、排名与上线检查清单.md"};function n(p,s,o,h,r,k){return i(),t("div",null,[...s[0]||(s[0]=[e(`<p>你要做的事情可以分成两块：<strong>先让搜索引擎能发现和收录你的页面，再让它觉得你的页面值得排在前面</strong>。SEO 不是提交一下网址就结束，提交只能加快发现，不保证收录或排名；Google 和百度官方都明确说过类似意思。(<a href="https://developers.google.com/search/docs/fundamentals/seo-starter-guide" title="SEO Starter Guide: The Basics | Google Search Central  |  Documentation  |  Google for Developers" target="_blank" rel="noreferrer">Google for Developers</a>)</p><ul><li>确定要登录的搜索引擎</li><li>先添加网站</li><li>再证明网站是我们的</li><li>提交sitemap.xml：sitemap.xml的url不会变，只是内容会变，搜索引擎会定期根据这个内容来爬页面</li><li>再每次页面发生变化时，通过手动或api告诉搜索引擎，让他更新收录</li></ul><h2 id="_1-先确保页面-能被爬虫看到" tabindex="-1">1. 先确保页面“能被爬虫看到” <a class="header-anchor" href="#_1-先确保页面-能被爬虫看到" aria-label="Permalink to &quot;1. 先确保页面“能被爬虫看到”&quot;">​</a></h2><p>先检查这些基础项：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://你的域名/</span></span>
<span class="line"><span>https://你的域名/robots.txt</span></span>
<span class="line"><span>https://你的域名/sitemap.xml</span></span></code></pre></div><p>你的页面最好满足：</p><ul><li>页面公开访问，不需要登录。</li><li>服务端返回状态码是 <code>200</code>，不要是 <code>403</code>、<code>404</code>、<code>500</code>。</li><li>不要在 <code>robots.txt</code> 里误写 <code>Disallow: /</code>。</li><li>页面里不要有 <code>noindex</code>。</li><li>主要内容尽量直接出现在 HTML 里，不要完全依赖前端 JS 异步渲染。</li></ul><p>如果你做的是 React/Vue 单页应用，建议重要页面用 <strong>SSR/SSG/预渲染</strong>，比如 Next.js、Nuxt、Astro、Vite SSG。Google 可以处理 JavaScript，但它的流程包括抓取、渲染、索引；对 SEO 来说，把核心内容直接输出到 HTML 通常更稳。(<a href="https://developers.google.com/search/docs/crawling-indexing/javascript/javascript-seo-basics?utm_source=chatgpt.com" title="Understand JavaScript SEO Basics | Google Search Central" target="_blank" rel="noreferrer">Google for Developers</a>)</p><h2 id="_2-做-robots-txt-和-sitemap-xml" tabindex="-1">2. 做 <code>robots.txt</code> 和 <code>sitemap.xml</code> <a class="header-anchor" href="#_2-做-robots-txt-和-sitemap-xml" aria-label="Permalink to &quot;2. 做 \`robots.txt\` 和 \`sitemap.xml\`&quot;">​</a></h2><p><code>robots.txt</code> 用来告诉爬虫哪些路径可以抓、哪些不抓；它不是用来防止页面出现在搜索结果里的，真不想被索引要用 <code>noindex</code> 或权限保护。(<a href="https://developers.google.com/search/docs/crawling-indexing/robots/intro?utm_source=chatgpt.com" title="Robots.txt Introduction and Guide | Google Search Central" target="_blank" rel="noreferrer">Google for Developers</a>)</p><p>可以先这样放：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User-agent: *</span></span>
<span class="line"><span>Allow: /</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Sitemap: https://你的域名/sitemap.xml</span></span></code></pre></div><p><code>sitemap.xml</code> 用来列出你希望搜索引擎发现的重要页面。Google 说明 sitemap 能帮助搜索引擎更高效地抓取网站，也可以提供页面更新时间、多语言版本等信息。(<a href="https://developers.google.com/search/docs/crawling-indexing/sitemaps/overview?utm_source=chatgpt.com" title="What Is a Sitemap | Google Search Central | Documentation" target="_blank" rel="noreferrer">Google for Developers</a>)</p><p>简单示例：</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">urlset</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> xmlns</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://www.sitemaps.org/schemas/sitemap/0.9&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">loc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;https://你的域名/&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">loc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">lastmod</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;2026-06-04&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">lastmod</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">loc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;https://你的域名/pricing&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">loc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">lastmod</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;2026-06-04&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">lastmod</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">urlset</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><h2 id="_3-主动提交到搜索引擎" tabindex="-1">3. 主动提交到搜索引擎 <a class="header-anchor" href="#_3-主动提交到搜索引擎" aria-label="Permalink to &quot;3. 主动提交到搜索引擎&quot;">​</a></h2><p>面向国内用户，优先做：</p><ul><li><strong>百度搜索资源平台</strong>：添加站点、验证域名、提交 sitemap 或 URL。</li><li><strong>必应站长平台</strong>：提交 sitemap，接入 IndexNow。</li><li><strong>360 搜索、搜狗搜索</strong>：也可以提交站点，但优先级通常低于百度和必应。</li><li>面向海外用户，再重点做 <strong>Google Search Console</strong>。</li></ul><p>Google Search Console 支持提交 sitemap、检查索引覆盖、查看 Google 如何抓取你的页面。(<a href="https://search.google.com/search-console/about?utm_source=chatgpt.com" title="Google Search Console" target="_blank" rel="noreferrer">Google</a>) 百度的普通收录 / 链接提交工具可以缩短百度爬虫发现链接的时间，但百度也明确说明这不能保证一定收录。(<a href="https://ziyuan.baidu.com/sitemap/index" title="普通收录_加快网站内容抓取，快速提交数据工具_站长工具_网站支持_百度搜索资源平台" target="_blank" rel="noreferrer">Ziyuan.baidu.com</a>) Bing 这边可以考虑 IndexNow，它允许你在页面新增或更新时主动通知搜索引擎。(<a href="https://www.bing.com/indexnow/getstarted?utm_source=chatgpt.com" title="How to add IndexNow to your website" target="_blank" rel="noreferrer">bing.com</a>)</p><h2 id="_4-每个页面都要有清晰的-seo-信息" tabindex="-1">4. 每个页面都要有清晰的 SEO 信息 <a class="header-anchor" href="#_4-每个页面都要有清晰的-seo-信息" aria-label="Permalink to &quot;4. 每个页面都要有清晰的 SEO 信息&quot;">​</a></h2><p>每个重要页面都应该有：</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;页面标题 - 品牌名&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">meta</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;description&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> content</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;一句话说明这个页面能解决什么问题&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">link</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> rel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;canonical&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> href</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://你的域名/当前页面&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><p>并且页面正文里要有：</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">h1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;这个页面的核心主题&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">h1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">h2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;子主题&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">h2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>不要所有页面都用同一个 title。比如：</p><ul><li>首页：<code>XXX - 面向开发者的 AI 工具导航</code></li><li>定价页：<code>XXX 定价 - 免费版与专业版对比</code></li><li>博客页：<code>如何用 XXX 自动生成 API 文档</code></li></ul><p>搜索引擎需要理解“这个页面是关于什么的”，用户也需要在搜索结果里一眼看懂点进去有什么价值。Google 的 SEO 入门文档也强调，SEO 的目标是帮助搜索引擎理解内容，并帮助用户判断是否访问你的网站。(<a href="https://developers.google.com/search/docs/fundamentals/seo-starter-guide" title="SEO Starter Guide: The Basics | Google Search Central  |  Documentation  |  Google for Developers" target="_blank" rel="noreferrer">Google for Developers</a>)</p><h2 id="_5-做真正有人会搜的内容" tabindex="-1">5. 做真正有人会搜的内容 <a class="header-anchor" href="#_5-做真正有人会搜的内容" aria-label="Permalink to &quot;5. 做真正有人会搜的内容&quot;">​</a></h2><p>如果你的网站只有一个首页，通常很难获得自然流量。你需要围绕用户会搜索的问题做页面，例如：</p><ul><li>产品页：你的工具解决什么问题。</li><li>对比页：<code>你的产品 vs 竞品</code>。</li><li>教程页：<code>如何用 xxx 做 yyy</code>。</li><li>案例页：真实使用场景。</li><li>FAQ 页：用户常问问题。</li><li>博客 / 文档：覆盖长尾关键词。</li></ul><p>比如你做的是“代码生成工具”，可以写：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>如何用 AI 生成 TypeScript 类型</span></span>
<span class="line"><span>如何自动生成 OpenAPI 文档</span></span>
<span class="line"><span>Cursor、Copilot、XXX 对比</span></span>
<span class="line"><span>前端项目如何自动生成接口请求代码</span></span></code></pre></div><p>这类页面比单纯写“最强 AI 工具”更容易匹配真实搜索需求。</p><h2 id="_6-加结构化数据" tabindex="-1">6. 加结构化数据 <a class="header-anchor" href="#_6-加结构化数据" aria-label="Permalink to &quot;6. 加结构化数据&quot;">​</a></h2><p>如果你有文章、产品、FAQ、软件应用、面包屑导航，可以加 JSON-LD 结构化数据。Google 说明结构化数据能帮助它理解页面内容，并让页面有机会获得更丰富的搜索展示效果。(<a href="https://developers.google.com/search/docs/appearance/structured-data/intro-structured-data" title="Intro to How Structured Data Markup Works | Google Search Central  |  Documentation  |  Google for Developers" target="_blank" rel="noreferrer">Google for Developers</a>)</p><p>例如软件产品页可以考虑：</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;application/ld+json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &quot;@context&quot;: &quot;https://schema.org&quot;,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &quot;@type&quot;: &quot;SoftwareApplication&quot;,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &quot;name&quot;: &quot;你的产品名&quot;,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &quot;applicationCategory&quot;: &quot;DeveloperApplication&quot;,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &quot;operatingSystem&quot;: &quot;Web&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><h2 id="_7-提升速度、移动端体验和稳定性" tabindex="-1">7. 提升速度、移动端体验和稳定性 <a class="header-anchor" href="#_7-提升速度、移动端体验和稳定性" aria-label="Permalink to &quot;7. 提升速度、移动端体验和稳定性&quot;">​</a></h2><p>搜索引擎不只看文字，也会看页面体验。Google 的 Core Web Vitals 关注加载性能、交互响应和视觉稳定性，并建议站长优化这些指标。(<a href="https://developers.google.com/search/docs/appearance/core-web-vitals?utm_source=chatgpt.com" title="Understanding Core Web Vitals and Google search results" target="_blank" rel="noreferrer">Google for Developers</a>)</p><p>你可以重点优化：</p><ul><li>首页首屏加载速度。</li><li>图片压缩，使用 WebP / AVIF。</li><li>JS bundle 不要太大。</li><li>移动端布局正常。</li><li>使用 HTTPS。</li><li>页面不要有遮挡内容的大弹窗。</li><li>重要按钮、链接可点击。</li><li>避免 CLS，图片和广告位预留尺寸。</li></ul><h2 id="_8-做内链和外链" tabindex="-1">8. 做内链和外链 <a class="header-anchor" href="#_8-做内链和外链" aria-label="Permalink to &quot;8. 做内链和外链&quot;">​</a></h2><p>站内要让搜索引擎能顺着链接发现页面：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>首页 -&gt; 产品页 -&gt; 教程页 -&gt; 案例页 -&gt; FAQ</span></span>
<span class="line"><span>博客文章 -&gt; 相关产品页</span></span>
<span class="line"><span>文档页 -&gt; 注册页 / Demo 页</span></span></code></pre></div><p>外部链接也很重要。你可以从这些地方获得自然链接：</p><ul><li>GitHub README。</li><li>技术博客。</li><li>掘金、知乎、V2EX、少数派、SegmentFault。</li><li>Product Hunt、Hacker News、Reddit，面向海外时。</li><li>朋友网站、合作伙伴、开源项目文档。</li><li>真实用户案例。</li></ul><p>不要买垃圾外链、堆关键词、隐藏文字、批量采集内容。这些短期可能有波动，长期容易被降权。</p><h2 id="_9-面向中国大陆用户时的额外事项" tabindex="-1">9. 面向中国大陆用户时的额外事项 <a class="header-anchor" href="#_9-面向中国大陆用户时的额外事项" aria-label="Permalink to &quot;9. 面向中国大陆用户时的额外事项&quot;">​</a></h2><p>如果你的网站主要服务国内用户，建议优先考虑：</p><ul><li>中文内容质量。</li><li>百度搜索资源平台。</li><li>国内访问速度。</li><li>移动端体验。</li><li>如果服务器在中国大陆，通常需要做 ICP 备案。中国相关规定要求，在境内提供非经营性互联网信息服务应履行备案手续，未经备案不得从事非经营性互联网信息服务。(<a href="https://amr.sz.gov.cn/xxgk/zcwj/scjgfg/dzswgl/jlglfl/content/post_11724725.html?utm_source=chatgpt.com" title="非经营性互联网信息服务备案管理办法 - 深圳市市场监督管理局" target="_blank" rel="noreferrer">Shenzhen Market Authority</a>)</li></ul><p>ICP备案本身不是“排名魔法”，但国内访问稳定性、速度、可信度会影响用户体验，也会间接影响搜索表现。</p><h2 id="_10-上线后的检查清单" tabindex="-1">10. 上线后的检查清单 <a class="header-anchor" href="#_10-上线后的检查清单" aria-label="Permalink to &quot;10. 上线后的检查清单&quot;">​</a></h2><p>上线后按这个顺序做：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 确认域名能正常访问</span></span>
<span class="line"><span>2. 配好 HTTPS</span></span>
<span class="line"><span>3. 配好 robots.txt</span></span>
<span class="line"><span>4. 生成 sitemap.xml</span></span>
<span class="line"><span>5. 每个页面设置 title / description / canonical</span></span>
<span class="line"><span>6. 重要页面使用 SSR / SSG / 预渲染</span></span>
<span class="line"><span>7. 提交百度搜索资源平台</span></span>
<span class="line"><span>8. 提交 Google Search Console</span></span>
<span class="line"><span>9. 提交 Bing Webmaster Tools</span></span>
<span class="line"><span>10. 接入统计工具</span></span>
<span class="line"><span>11. 每周看收录、点击、关键词、抓取异常</span></span>
<span class="line"><span>12. 持续新增高质量内容</span></span></code></pre></div><p>你可以用这些搜索指令检查有没有被收录：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>site:你的域名</span></span>
<span class="line"><span>site:你的域名 关键词</span></span></code></pre></div><p>刚上线的网站不要期待马上有排名。Google 官方也提到，SEO 改动生效可能从几个小时到几个月不等，通常需要观察几周。(<a href="https://developers.google.com/search/docs/fundamentals/seo-starter-guide" title="SEO Starter Guide: The Basics | Google Search Central  |  Documentation  |  Google for Developers" target="_blank" rel="noreferrer">Google for Developers</a>)</p><p>最小可行版本可以这样做：<strong>先把首页、产品页、文档页、博客页做成可被爬虫直接读取的 HTML；加 sitemap；提交百度、Google、Bing；然后每周围绕用户会搜索的问题写 2-3 篇高质量页面。</strong></p>`,58)])])}const g=a(l,[["render",n]]);export{c as __pageData,g as default};
